/* ── Vault of Embers ─────────────────────────────────────────── */
:root {
  --ink: #07060c;
  --ink-2: #0d0b16;
  --panel: rgba(12, 10, 20, 0.72);
  --panel-line: rgba(240, 179, 90, 0.16);
  --paper: #efe4cf;
  --muted: #9a8fa8;
  --gold: #f0b35a;
  --gold-soft: #ffd79a;
  --ember: #ff8b3d;
  --red: #e0555f;
  --red-deep: #8e2f3d;
  --green: #86d98a;
  --violet: #b98bff;
  --font-display: "Palatino Linotype", "Book Antiqua", Palatino, Georgia, serif;
  --font-ui: ui-monospace, "SF Mono", "Cascadia Mono", Menlo, Consolas, monospace;
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  overscroll-behavior: none;
}

#app {
  position: fixed;
  inset: 0;
  overflow: hidden;
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

#game {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  image-rendering: pixelated;
  background: #07060c;
}

.fx { position: absolute; inset: 0; pointer-events: none; z-index: 2; }

#vignette {
  background:
    radial-gradient(ellipse 78% 72% at 50% 46%, transparent 38%, rgba(4, 3, 9, 0.42) 78%, rgba(2, 2, 5, 0.82) 100%),
    linear-gradient(to bottom, rgba(4, 3, 9, 0.35), transparent 18%, transparent 82%, rgba(4, 3, 9, 0.5));
  mix-blend-mode: multiply;
}

#grain {
  opacity: 0.16;
  background-image: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.035) 0 1px, transparent 1px 3px);
  mix-blend-mode: overlay;
}

#lowhp {
  opacity: 0;
  transition: opacity 0.6s ease;
  box-shadow: inset 0 0 160px 40px rgba(150, 20, 35, 0.55);
  animation: breathe 2.6s ease-in-out infinite;
}
body.low-hp #lowhp { opacity: 1; }
@keyframes breathe { 0%, 100% { opacity: 0.5; } 50% { opacity: 1; } }

#hurt-flash {
  opacity: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(170, 24, 42, 0.55) 100%);
}
#hurt-flash.on { animation: hurt 0.42s ease-out; }
@keyframes hurt { 0% { opacity: 0.9; } 100% { opacity: 0; } }

/* ── HUD ─────────────────────────────────────────────────────── */
#hud {
  position: absolute;
  top: 0; left: 0; right: 0;
  z-index: 5;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  padding: calc(14px + var(--safe-t)) calc(18px + var(--safe-r)) 0 calc(18px + var(--safe-l));
  gap: 16px;
  pointer-events: none;
}

.hud-left {
  display: flex;
  gap: 22px;
  align-items: flex-start;
  padding: 12px 16px 11px;
  background: linear-gradient(180deg, rgba(10, 8, 17, 0.8), rgba(10, 8, 17, 0.45));
  border: 1px solid var(--panel-line);
  border-radius: 4px;
  box-shadow: 0 10px 40px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 220, 170, 0.06);
  backdrop-filter: blur(7px);
}

.depth-block { min-width: 128px; }
.depth-line {
  display: flex;
  align-items: baseline;
  gap: 5px;
  font-size: 19px;
  letter-spacing: 0.06em;
  color: var(--gold-soft);
  text-shadow: 0 0 18px rgba(240, 179, 90, 0.35);
}
.depth-line #depth { font-size: 26px; font-weight: 700; line-height: 1; }
.minor {
  font-size: 9px;
  letter-spacing: 0.22em;
  color: var(--muted);
  text-transform: uppercase;
}
.floor-name {
  margin-top: 4px;
  font-family: var(--font-display);
  font-size: 12px;
  font-style: italic;
  letter-spacing: 0.04em;
  color: #cbbfd6;
  white-space: nowrap;
}

.vitals { min-width: 208px; }
.vital-row { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }
.vital-num { font-size: 11px; color: #e8d9c3; letter-spacing: 0.06em; }
.bar {
  position: relative;
  height: 8px;
  border-radius: 2px;
  background: rgba(255, 255, 255, 0.07);
  overflow: hidden;
  margin-bottom: 4px;
  box-shadow: inset 0 1px 2px rgba(0, 0, 0, 0.6);
}
.bar i {
  display: block;
  height: 100%;
  width: 100%;
  transform-origin: left center;
  transition: width 0.22s ease;
}
.bar.hp i {
  background: linear-gradient(90deg, #9c2433, #e0555f 55%, #ff8d86);
  box-shadow: 0 0 10px rgba(224, 85, 95, 0.55);
}
.bar.xp { height: 3px; margin-bottom: 7px; }
.bar.xp i { background: linear-gradient(90deg, #7b5b2c, var(--gold)); box-shadow: 0 0 8px rgba(240, 179, 90, 0.4); }
.loadout { display: flex; gap: 6px; font-size: 9px; letter-spacing: 0.09em; color: #9e92b0; white-space: nowrap; }
.loadout .dot { color: #5f556e; }
.loadout .equip { color: #cdbf9e; overflow: hidden; text-overflow: ellipsis; max-width: 120px; }

.hud-right { display: flex; gap: 8px; align-items: center; pointer-events: auto; }
.chip {
  display: flex;
  align-items: center;
  gap: 6px;
  height: 38px;
  padding: 0 11px;
  background: var(--panel);
  border: 1px solid var(--panel-line);
  border-radius: 4px;
  color: var(--gold);
  font-family: var(--font-ui);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.35), inset 0 1px 0 rgba(255, 220, 170, 0.05);
  backdrop-filter: blur(7px);
}
.chip svg { width: 17px; height: 17px; flex: none; }
.chip b { color: var(--paper); font-size: 13px; font-weight: 600; }
.chip em {
  font-style: normal;
  font-size: 8px;
  color: #8b7f9c;
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-radius: 2px;
  padding: 1px 3px;
  line-height: 1;
}
.chip-btn { cursor: pointer; transition: border-color 0.15s, background 0.15s, transform 0.08s; }
.chip-btn:hover { border-color: rgba(240, 179, 90, 0.5); background: rgba(26, 20, 34, 0.86); }
.chip-btn:active { transform: translateY(1px); }
.chip-btn.empty { opacity: 0.42; }
.chip-btn.empty b { color: #8b7f9c; }
.icon-btn {
  width: 38px; height: 38px;
  display: grid; place-items: center;
  background: var(--panel);
  border: 1px solid var(--panel-line);
  border-radius: 4px;
  color: #b9adc7;
  cursor: pointer;
  backdrop-filter: blur(7px);
  transition: color 0.15s, border-color 0.15s;
}
.icon-btn:hover { color: var(--gold); border-color: rgba(240, 179, 90, 0.45); }
.icon-btn svg { width: 19px; height: 19px; }
.icon-btn .snd-off { display: none; }
.icon-btn.muted .snd-on { display: none; }
.icon-btn.muted .snd-off { display: block; }

/* ── log ─────────────────────────────────────────────────────── */
#log {
  position: absolute;
  left: calc(18px + var(--safe-l));
  bottom: calc(52px + var(--safe-b));
  z-index: 5;
  width: min(390px, 42vw);
  padding: 9px 12px 10px;
  background: linear-gradient(90deg, rgba(9, 8, 15, 0.82), rgba(9, 8, 15, 0.35) 82%, transparent);
  border-left: 2px solid rgba(240, 179, 90, 0.22);
  pointer-events: none;
}
.log-title { display: flex; align-items: center; gap: 8px; margin-bottom: 5px; }
.log-title span { font-size: 8px; letter-spacing: 0.3em; color: #7b6f8b; }
.log-title i { flex: 1; height: 1px; background: linear-gradient(90deg, rgba(240, 179, 90, 0.18), transparent); }
#log-lines { display: flex; flex-direction: column; gap: 3px; }
.log-line {
  font-family: var(--font-ui);
  font-size: 11px;
  line-height: 1.35;
  color: #cabfd4;
  text-shadow: 0 1px 3px #000;
  animation: log-in 0.24s ease-out;
  transition: opacity 0.4s;
}
.log-line:nth-last-child(n+4) { opacity: 0.48; }
.log-line.gold { color: var(--gold-soft); }
.log-line.good { color: var(--green); }
.log-line.bad { color: #ff8b8b; }
.log-line.magic { color: var(--violet); }
.log-line.story { color: var(--gold); font-style: italic; }
@keyframes log-in { from { opacity: 0; transform: translateX(-4px); } to { opacity: 1; transform: none; } }

/* ── stairs hint ─────────────────────────────────────────────── */
#stair-hint {
  position: absolute;
  left: 50%;
  bottom: calc(88px + var(--safe-b));
  transform: translateX(-50%);
  z-index: 6;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 16px;
  background: rgba(20, 14, 8, 0.85);
  border: 1px solid rgba(240, 179, 90, 0.45);
  border-radius: 3px;
  color: var(--gold-soft);
  font-size: 10px;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  box-shadow: 0 0 26px rgba(240, 179, 90, 0.18);
  animation: hint-pulse 2s ease-in-out infinite;
  pointer-events: none;
}
#stair-hint .key {
  border: 1px solid rgba(240, 179, 90, 0.4);
  padding: 2px 5px;
  border-radius: 2px;
  font-size: 9px;
  color: var(--gold);
}
@keyframes hint-pulse { 0%, 100% { box-shadow: 0 0 18px rgba(240, 179, 90, 0.1); } 50% { box-shadow: 0 0 32px rgba(240, 179, 90, 0.28); } }
.hidden { display: none !important; }

/* ── minimap ─────────────────────────────────────────────────── */
#minimap-wrap {
  position: absolute;
  right: calc(18px + var(--safe-r));
  bottom: calc(52px + var(--safe-b));
  z-index: 5;
  width: 196px;
  padding: 8px 8px 6px;
  background: var(--panel);
  border: 1px solid var(--panel-line);
  border-radius: 4px;
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(7px);
  pointer-events: none;
}
.map-title { display: flex; justify-content: space-between; align-items: center; margin: 0 2px 5px; }
.map-title span { font-size: 8px; letter-spacing: 0.26em; color: #7b6f8b; }
.map-title b { font-family: var(--font-display); font-size: 12px; color: var(--gold); font-weight: 400; }
#minimap { display: block; width: 180px; height: 116px; border: 1px solid rgba(255, 255, 255, 0.05); background: rgba(4, 3, 8, 0.6); image-rendering: pixelated; }

/* ── hint bar ────────────────────────────────────────────────── */
#hintbar {
  position: absolute;
  left: 50%;
  bottom: calc(16px + var(--safe-b));
  transform: translateX(-50%);
  z-index: 5;
  display: flex;
  gap: 18px;
  padding: 6px 14px;
  font-size: 9px;
  letter-spacing: 0.06em;
  color: #7d7189;
  background: rgba(8, 7, 14, 0.45);
  border-radius: 3px;
  pointer-events: none;
  white-space: nowrap;
}
#hintbar b { color: #b8a98f; font-weight: 600; }

/* ── touch controls ──────────────────────────────────────────── */
#touch-controls { display: none; }

/* ── overlays ────────────────────────────────────────────────── */
.overlay {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: grid;
  place-items: center;
  padding: calc(24px + var(--safe-t)) calc(24px + var(--safe-r)) calc(24px + var(--safe-b)) calc(24px + var(--safe-l));
  background:
    radial-gradient(ellipse 70% 62% at 50% 44%, rgba(24, 15, 30, 0.42), rgba(4, 3, 8, 0.9) 74%, rgba(2, 2, 5, 0.97)),
    linear-gradient(to bottom, rgba(5, 4, 9, 0.75), rgba(5, 4, 9, 0.93));
  backdrop-filter: blur(2.5px);
  overflow: hidden;
}
.overlay::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.018) 0 1px, transparent 1px 3px);
}
.overlay-glow {
  position: absolute;
  width: 900px; height: 900px;
  left: 50%; top: 48%;
  transform: translate(-50%, -50%);
  background: radial-gradient(circle, rgba(240, 140, 60, 0.13), rgba(160, 60, 120, 0.05) 45%, transparent 70%);
  pointer-events: none;
  animation: glow-drift 9s ease-in-out infinite alternate;
}
@keyframes glow-drift { from { opacity: 0.6; transform: translate(-52%, -50%) scale(0.95); } to { opacity: 1; transform: translate(-48%, -47%) scale(1.08); } }

.title-inner {
  position: relative;
  z-index: 1;
  width: min(620px, 100%);
  text-align: center;
  animation: rise 0.7s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}
@keyframes rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }

.eyebrow {
  margin: 0 0 18px;
  font-size: 9px;
  letter-spacing: 0.42em;
  color: #a98a63;
  text-transform: uppercase;
}
.eyebrow.red { color: #d4616b; }
.eyebrow.gold { color: var(--gold); }

h1 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(46px, 9vw, 82px);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #f2e3c8;
  text-shadow:
    0 0 40px rgba(240, 150, 70, 0.28),
    0 0 90px rgba(224, 90, 60, 0.16),
    0 3px 0 rgba(0, 0, 0, 0.6);
}
h1 span {
  display: block;
  font-size: 0.32em;
  letter-spacing: 0.5em;
  color: var(--gold);
  margin: 0.22em 0 0.12em;
  text-indent: 0.5em;
  font-style: italic;
}
.tagline {
  margin: 22px auto 0;
  font-family: var(--font-display);
  font-style: italic;
  font-size: clamp(13px, 1.7vw, 16px);
  line-height: 1.7;
  color: #bdafc2;
}
.title-cta { margin-top: 30px; display: flex; flex-direction: column; align-items: center; gap: 12px; }
.best-line { font-size: 8px; letter-spacing: 0.24em; color: #7f728d; }
.best-line b { color: #c4b394; font-weight: 500; margin-left: 6px; }

.btn-primary {
  position: relative;
  cursor: pointer;
  padding: 15px 58px;
  font-family: var(--font-ui);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.34em;
  text-transform: uppercase;
  color: #1a0f08;
  background: linear-gradient(180deg, #ffd79a, #e9a649 55%, #c9802f);
  border: 1px solid #ffe6bb;
  border-radius: 2px;
  box-shadow:
    0 0 0 4px rgba(240, 179, 90, 0.08),
    0 8px 34px rgba(240, 150, 60, 0.32),
    inset 0 1px 0 rgba(255, 255, 255, 0.6);
  text-indent: 0.34em;
  transition: transform 0.12s ease, box-shadow 0.2s ease, filter 0.2s;
}
.btn-primary::before {
  content: "";
  position: absolute;
  inset: 4px;
  border: 1px solid rgba(66, 34, 8, 0.3);
  border-radius: 1px;
  pointer-events: none;
}
.btn-primary:hover { filter: brightness(1.08); box-shadow: 0 0 0 5px rgba(240, 179, 90, 0.12), 0 10px 44px rgba(255, 165, 70, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.7); }
.btn-primary:active { transform: translateY(1px); }

.controls {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px 26px;
  margin: 38px auto 0;
  padding-top: 24px;
  border-top: 1px solid rgba(240, 179, 90, 0.12);
  max-width: 520px;
  text-align: left;
  font-size: 10px;
  letter-spacing: 0.06em;
  color: #9e92ae;
}
.controls > div { display: flex; align-items: center; gap: 8px; }
.kbd-group { display: inline-flex; gap: 3px; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 19px;
  padding: 3px 5px;
  font-family: var(--font-ui);
  font-size: 9px;
  color: #d9c9ad;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.14);
  border-bottom-color: rgba(255, 255, 255, 0.24);
  border-radius: 2px;
  line-height: 1;
}
.footnote { margin: 26px 0 0; font-size: 8px; letter-spacing: 0.16em; color: #6a5f77; }
.footnote kbd { margin: 0 2px; }

/* end screens */
.end { background: radial-gradient(ellipse 70% 60% at 50% 42%, rgba(60, 14, 20, 0.35), rgba(5, 3, 7, 0.94) 72%), rgba(4, 3, 7, 0.86); }
.end-inner {
  position: relative;
  z-index: 1;
  width: min(460px, 100%);
  text-align: center;
  animation: rise 0.6s ease both;
}
.end h2 {
  margin: 0;
  font-family: var(--font-display);
  font-size: clamp(42px, 9vw, 66px);
  font-weight: 400;
  letter-spacing: 0.14em;
  color: #f0d9d2;
  text-shadow: 0 0 46px rgba(190, 40, 55, 0.4);
}
.end.win .end h2, .end-inner.win h2 { color: #ffe3b0; text-shadow: 0 0 50px rgba(255, 180, 70, 0.5); }
.end-line { margin: 12px 0 26px; font-family: var(--font-display); font-style: italic; font-size: 14px; color: #a99caf; }
.stat-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 0 0 30px;
  background: rgba(255, 255, 255, 0.07);
  border: 1px solid rgba(255, 255, 255, 0.07);
}
.stat-grid div { padding: 12px 6px 11px; background: rgba(10, 8, 15, 0.92); }
.stat-grid span { display: block; font-size: 7px; letter-spacing: 0.24em; color: #786d85; margin-bottom: 5px; }
.stat-grid b { font-family: var(--font-display); font-size: 20px; font-weight: 400; color: #e6d4b7; }
.end .btn-primary { padding: 14px 38px; font-size: 11px; letter-spacing: 0.24em; }

/* ── responsive ──────────────────────────────────────────────── */
@media (max-width: 900px) {
  #minimap-wrap { display: none; }
  #hintbar { display: none; }
  #log { width: min(360px, 62vw); bottom: calc(16px + var(--safe-b)); }
  .hud-left { padding: 9px 12px; gap: 14px; }
  .vitals { min-width: 168px; }
  .loadout { display: none; }
  .floor-name { font-size: 10px; }
  .depth-line { font-size: 15px; }
  .depth-line #depth { font-size: 21px; }
  .title-inner { width: min(480px, 100%); }
  .controls { grid-template-columns: 1fr; gap: 10px; max-width: 340px; }
}

@media (max-width: 640px) {
  #hud { padding: calc(9px + var(--safe-t)) calc(9px + var(--safe-r)) 0 calc(9px + var(--safe-l)); gap: 8px; }
  .hud-left { flex: 1; min-width: 0; }
  .depth-block { min-width: 78px; }
  .floor-name { max-width: 118px; overflow: hidden; text-overflow: ellipsis; }
  .vitals { flex: 1; min-width: 0; }
  .hud-right { gap: 5px; flex-wrap: wrap; justify-content: flex-end; max-width: 132px; }
  .chip { height: 32px; padding: 0 8px; gap: 4px; }
  .chip svg { width: 14px; height: 14px; }
  .chip b { font-size: 11px; }
  .chip em { display: none; }
  .icon-btn { width: 32px; height: 32px; }
  #log { left: calc(10px + var(--safe-l)); bottom: calc(14px + var(--safe-b)); width: 56vw; max-width: 300px; background: linear-gradient(90deg, rgba(8, 7, 13, 0.7), transparent); padding: 6px 8px; }
  .log-line { font-size: 10px; }
  .log-line:nth-last-child(n+3) { opacity: 0.42; }
  #log-lines .log-line { max-height: 40px; overflow: hidden; }
  .log-title { margin-bottom: 2px; }
  h1 { letter-spacing: 0.06em; }
  .eyebrow { letter-spacing: 0.28em; font-size: 8px; margin-bottom: 14px; }
  .tagline { font-size: 12px; margin-top: 16px; }
  .title-cta { margin-top: 22px; }
  .controls { margin-top: 26px; padding-top: 18px; }
  .btn-primary { padding: 14px 44px; }
  .stat-grid b { font-size: 17px; }
}

/* touch-enabled layout */
body.touch #hintbar { display: none; }
body.touch #touch-controls {
  display: flex;
  position: absolute;
  left: 0; right: 0;
  bottom: calc(12px + var(--safe-b));
  z-index: 7;
  justify-content: space-between;
  align-items: flex-end;
  padding: 0 calc(14px + var(--safe-r)) 0 calc(14px + var(--safe-l));
  pointer-events: none;
}
body.touch #touch-controls > * { pointer-events: auto; }

.dpad {
  display: grid;
  grid-template-columns: repeat(3, 52px);
  grid-template-rows: repeat(3, 52px);
  filter: drop-shadow(0 10px 24px rgba(0, 0, 0, 0.5));
}
.dpad-btn {
  display: grid;
  place-items: center;
  border: 1px solid rgba(240, 179, 90, 0.24);
  background: linear-gradient(180deg, rgba(28, 23, 39, 0.82), rgba(13, 11, 20, 0.86));
  color: #d8c5a5;
  font-size: 15px;
  border-radius: 5px;
  touch-action: none;
  transition: background 0.1s, color 0.1s;
}
.dpad-btn:active, .dpad-btn.pressed { background: rgba(240, 179, 90, 0.3); color: #fff2d4; }
.dpad-btn.up { grid-area: 1 / 2; border-radius: 6px 6px 3px 3px; }
.dpad-btn.left { grid-area: 2 / 1; border-radius: 6px 3px 3px 6px; }
.dpad-btn.right { grid-area: 2 / 3; border-radius: 3px 6px 6px 3px; }
.dpad-btn.down { grid-area: 3 / 2; border-radius: 3px 3px 6px 6px; }
.dpad-hub { grid-area: 2 / 2; border: 1px solid rgba(240, 179, 90, 0.12); background: rgba(10, 8, 17, 0.7); }

.touch-actions { display: flex; flex-direction: column; gap: 8px; align-items: stretch; width: 132px; }
.touch-btn {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 8px;
  padding: 12px 12px;
  font-family: var(--font-ui);
  font-size: 9px;
  letter-spacing: 0.16em;
  color: #cbbda6;
  background: linear-gradient(180deg, rgba(28, 23, 39, 0.82), rgba(13, 11, 20, 0.86));
  border: 1px solid rgba(240, 179, 90, 0.24);
  border-radius: 5px;
  touch-action: none;
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.4);
}
.touch-btn b { color: var(--gold); font-size: 11px; }
.touch-btn:active { background: rgba(240, 179, 90, 0.28); color: #fff; }
.touch-btn.empty { opacity: 0.45; }
.touch-btn.wide { justify-content: center; }
.touch-btn.ready { border-color: rgba(240, 179, 90, 0.7); color: var(--gold-soft); box-shadow: 0 0 22px rgba(240, 179, 90, 0.22); }

body.touch #log { bottom: calc(190px + var(--safe-b)); width: 54vw; max-width: 330px; }
@media (max-height: 560px) {
  body.touch #log { display: none; }
  .dpad { grid-template-columns: repeat(3, 44px); grid-template-rows: repeat(3, 44px); }
  .touch-actions { width: 112px; gap: 5px; }
  .touch-btn { padding: 9px 10px; }
  .title-inner .controls { display: none; }
  .overlay { align-items: start; overflow-y: auto; }
  h1 { font-size: 40px; }
}
@media (min-width: 901px) {
  body.touch #touch-controls { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .overlay-glow, #lowhp { animation: none; }
  .title-inner, .end-inner { animation: none; }
}
